[Form]
public class NVHcmManualLeaveAdjustment extends FormRun
{
    LeaveTmpForecastedBalance leaveTmpForecastedBalance;

}

public void init()
{
    super();

    if (!element.args() || !element.args().caller())
    {
        throw error("@SYS22539");
    }

    leaveTmpForecastedBalance = element.args().record() as LeaveTmpForecastedBalance;

    FldLeaveTransactionType.selection(LeaveTransactionType::BalanceAdjustment);
}

public void clicked()
{
    int days = FldAdjustmentDays.value();

    if(days == 0)
        throw error("Adjustment days must be specified.");

    LeaveType leaveType = LeaveType::findByType(leaveTmpForecastedBalance.Type);

    if(leaveType.RecId == 0)
        throw error("Leave type not found.");

    if(leaveTmpForecastedBalance.Worker == 0)
        throw error("Worker not found.");

    ttsbegin;
    LeaveBankTransaction leaveBankTransaction;
    leaveBankTransaction.clear();

    leaveBankTransaction.Worker             = leaveTmpForecastedBalance.Worker;
    leaveBankTransaction.LeavePlan          = NVLeavePlanEventHandler::getPlanForLeaveType(leaveType.RecId, leaveBankTransaction.Worker).RecId;
    leaveBankTransaction.LeaveType          = leaveType.RecId;
    leaveBankTransaction.TransactionDate    =  HcmDateTimeUtil::companyCurrentDate();
    leaveBankTransaction.TransactionType    = FldLeaveTransactionType.selection();
    leaveBankTransaction.NVLeaveCategory    = FldLeaveCategory.selection();
    leaveBankTransaction.Amount             = days;
    leaveBankTransaction.Comment            = "";

    leaveBankTransaction.insert();
    ttscommit;

    info("Leave adjusted.");

    super();
}
